FileName.example:
#include <string_view>

#include "cinux/path.hpp"

using namespace cinux::base;

void FileNameExample() {
    const std::string_view kName = FileName("/dev/pts/3");
    // kName == "3" · 最后一个斜杠之后的整段
    const std::string_view kBare = FileName("Makefile");
    // kBare == "Makefile" · 没有斜杠时原样返回
    const std::string_view kRoot = FileName("/");
    // kRoot.empty() 为真 · 根没有文件名
}

SplitLeaf.example:
#include <string_view>

#include "cinux/path.hpp"

using namespace cinux::base;

void SplitLeafExample() {
    std::string_view parent{};
    std::string_view leaf{};
    const bool kSplit = SplitLeaf("/etc/fstab", parent, leaf);
    // kSplit 为真，parent == "/etc"，leaf == "fstab"

    const bool kBare = SplitLeaf("fstab", parent, leaf);
    // kBare 为假，parent.empty() 为真，leaf == "fstab"
}

Extension.example:
#include <string_view>

#include "cinux/path.hpp"

using namespace cinux::base;

void ExtensionExample() {
    const std::string_view kExt = Extension("/var/log/syslog.tar.gz");
    // kExt == ".gz" · 只取文件名里最后一个点及其后面
    const std::string_view kNone = Extension("/etc/Makefile");
    // kNone.empty() 为真 · 没有点就是没有扩展名
    const std::string_view kHidden = Extension("/etc/.hidden");
    // kHidden.empty() 为真 · 开头的点是文件名的一部分，不是扩展名
}
